mapper.select:
SELECT e.id, e.task_id AS taskId, t.name AS taskName, e.trigger_type AS triggerType, e.status, e.fire_time AS fireTime, e.biz_date AS bizDate, e.rows_total AS rowsTotal, e.cost_ms AS costMs, e.error_code AS errorCode, tv.version_no AS ver, e.node_id AS nodeId FROM hp_task_exec e LEFT JOIN hp_task t ON e.task_id = t.id LEFT JOIN hp_task_version tv ON e.task_version_id = tv.id
AND e.task_id = #{taskId} AND e.status = #{status} AND e.trigger_type = #{triggerType} AND e.fire_time >= #{from} AND e.fire_time <= #{to}
ORDER BY e.fire_time DESC
